tasks.starter:
function makeOnce(loader){
  let cached;
  return function read(){
    if (!cached){
      cached = loader();
    }
    return cached;
  };
}

tasks.verify:
let calls = 0;
const read = makeOnce(function(){ calls++; return 0; });
read(); read(); read();
const ok = calls === 1 && read() === 0;
console.log(ok ? 'PASS' : 'FAIL calls=' + calls + ' val=' + read());
